// === Tab: mySketch ===
/*
Hey sableraph and friends! 
This is a fork of a fork that is suppose to resemble the planet Saturn!
The background, planet and rings all change to the music.
Can be viewed with music or without!

Hope you all enjoy!

Music by <a href="https://pixabay.com/users/lexin_music-28841948/?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=115667">Aleksey Chistilin</a> from <a href="https://pixabay.com/music//?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=115667">Pixabay</a>
Attribution: KomaTebe
*/

let f=0;
let W=900;
let counter=0
preload=_=> 
{
	soundFormats('mp3', "wav");
  song = loadSound('https://openprocessing.org/sketch/2132175/files/spaceMusic.mp3');//load song
}

setup=_=>
{
	createCanvas(1300, 700);
	pixelDensity(.42)
	song.play()
  amp = new p5.Amplitude();
	song.loop()
}
draw=_=>
{
	var vol = amp.getLevel();
  volumeLevel = round(map(vol, 0, 0.3,1, 50));
	counter++
  let r=W;
  background(volumeLevel/4);
  translate(1300/2,700/2);
  rotate(f/W);
  if(r>0)
	{
    for(z=255; z>=0; z-=2+random(1))
		{
			for(n=0;n<2;n++) 
				{
					fill(255)
					stroke(255)
					strokeWeight(random(1,2))
					arc(random(-1300,1300),random(-700,700),random(1),random(1),0.1,3.14)      //stars
				}
      	for(i=0;i<TAU;i+=PI/(28-random(2))) 
				{
					let n=noise(i,tan(i)/90000,(f+z)/10);
					push();
					rotate(i);
					strokeWeight( (volumeLevel/8.5) - random(3) )
					stroke(W-z);
					fill(34,34,34,35)
					arc(0,n,random(0,80),random(0,80),1,2);																			//saturn
					noFill()
					stroke(i+W,47);
					arc(0,z*n,200,200,1,2);																											//inner rings
					arc(0,z*n,500,500,1,2);																											//outer rings
					pop();
					r--;
      	}
     }
   }
  f-=2;
}

